import{_ as a,o as p,a as n,b as l}from"./app.C41L12d5.js";const c="/ascendc.github.io/assets/bilinearInterpolation_1.DsXe7CDt.png",t="/ascendc.github.io/assets/bilinearInterpolation_2.DtIh-kUo.png",m=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"基础API","link":"/api/SIMD-API/basic_api/basic_api"},{"text":"Memory矢量计算","link":"/api/SIMD-API/basic_api/memory_vector_compute/memory_vector_compute"},{"text":"基础算术","link":"/api/SIMD-API/basic_api/memory_vector_compute/basic_arithmetic/basic_arithmetic"},{"text":"BilinearInterpolation(ISASI)","link":"/api/SIMD-API/basic_api/memory_vector_compute/basic_arithmetic/BilinearInterpolation_ISASI"}]},"headers":[],"relativePath":"api/SIMD-API/basic_api/memory_vector_compute/basic_arithmetic/BilinearInterpolation_ISASI.md","filePath":"api/SIMD-API/basic_api/memory_vector_compute/basic_arithmetic/BilinearInterpolation_ISASI.md","outlineHeaders":[{"level":2,"title":"产品支持情况","slug":"产品支持情况","link":"#产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明","link":"#功能说明"},{"level":2,"title":"函数原型","slug":"函数原型","link":"#函数原型"},{"level":2,"title":"参数说明","slug":"参数说明","link":"#参数说明"},{"level":3,"title":"模板参数及接口参数说明","slug":"模板参数及接口参数说明","link":"#模板参数及接口参数说明"},{"level":3,"title":"sharedTmpBuffer空间说明","slug":"sharedTmpBuffer空间说明","link":"#sharedTmpBuffer空间说明"},{"level":2,"title":"数据类型","slug":"数据类型","link":"#数据类型"},{"level":2,"title":"返回值说明","slug":"返回值说明","link":"#返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明","link":"#约束说明"},{"level":2,"title":"调用示例","slug":"调用示例","link":"#调用示例"}],"lastUpdated":1788159000000}'),e={name:"api/SIMD-API/basic_api/memory_vector_compute/basic_arithmetic/BilinearInterpolation_ISASI.md"};function r(i,s,o,d,h,f){return p(),n("div",null,[...s[0]||(s[0]=[l('<div><article class="markdown-body"><h1>BilinearInterpolation(ISASI)<span id="ZH-CN_TOPIC_0000001786742102"></span></h1><h2 id="产品支持情况">产品支持情况<span id="section1550532418810"></span><a class="header-anchor" href="#产品支持情况">​</a></h2><div data-filter="950"><ul><li>Ascend 950PR/Ascend 950DT：支持</li></ul></div><div data-filter="A3"><ul><li>Atlas A3 训练系列产品/Atlas A3 推理系列产品：支持</li></ul></div><div data-filter="910b"><ul><li>Atlas A2 训练系列产品/Atlas A2 推理系列产品：支持</li></ul></div><div data-filter="310b"><ul><li>Atlas 200I/500 A2 推理产品：不支持</li></ul></div><div data-filter="310p"><ul><li>Atlas 推理系列产品AI Core：支持</li></ul></div><div data-filter="310p"><ul><li>Atlas 推理系列产品Vector Core：不支持</li></ul></div><div data-filter="910"><ul><li>Atlas 训练系列产品：不支持</li></ul></div><h2 id="功能说明">功能说明<span id="section618mcpsimp"></span><a class="header-anchor" href="#功能说明">​</a></h2><p>头文件路径为：<code>&quot;basic_api/kernel_operator_vec_bilinearinterpolation_intf.h&quot;</code>。</p><p>BilinearInterpolation属于双目矢量类计算接口，核心通过水平迭代+垂直迭代的双层循环完成乘累加运算，适用于非规则数据访问+权重乘加的向量运算场景（数据Gather+Multiply+Reduce）。</p><p>注：该接口是为了兼容旧款产品接口而添加的软仿接口。</p><p>具体计算流程参考下图：</p><p><strong>图1</strong> BilinearInterpolation计算流程示意图</p><p><img src="'+c+'" alt></p><p><img src="'+t+`" alt></p><p>结合上面的计算流程示意图，下面以一个具体示例，来介绍BilinearInterpolation整个计算过程。</p><p>假设计算场景的输入如下：</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>src0 = [1, 2, 3, ..., 512]，共计512个half数据；
src0Offset = [0, 32, 64, ..., 992]，共计32个uint32数据；
src1 = [2, 3, 4, ..., 33]，共计32个half数据；
hRepeat = 2；vRepeat = 2；mask = 128；vROffset = 128。
</code></pre></div><p>具体计算流程拆解分析如下：</p><ul><li><p>步骤1. 按DataBlock粒度，收集输入src0张量到临时Buffer。</p><p>总共hRepeat * vRepeat次迭代，每个迭代从输入的src0Offset读取8个偏移值，每个偏移值指向src0的一个DataBlock起始地址。</p><p>调用<a href="../scatter_gather/Gatherb_ISASI.html">Gatherb</a>接口，Gatherb接口接受输入张量（src0）、DataBlock偏移张量（src0Offset），根据src0Offset将输入张量src0按DataBlock（32Bytes）收集到临时张量（sharedTmpBuffer）中。</p><p>该步骤处理过程如下：</p><ul><li>总迭代次数：hRepeat * vRepeat = 2 * 2 = 4；</li><li>每次迭代处理的src0元素个数：8 * 32 / sizeof(half) = 128（8：DataBlock的数量；32：每个DataBlock的大小为32B）；</li><li>每次迭代收集结果 <ul><li>迭代0：sharedTmpBuffer[0:127] = [1, 2, ..., 128]；</li><li>迭代1：sharedTmpBuffer[128:255] = [129, 130, ..., 256]；</li><li>迭代2：sharedTmpBuffer[256:383] = [257, 258, ..., 384]；</li><li>迭代3：sharedTmpBuffer[384:511] = [385, 386, ..., 512]。</li></ul></li></ul></li><li><p>步骤2. 将输入的张量src1进行广播填充。</p><p>调用<a href="../data_padding/Brcb.html">Brcb</a>接口，每次迭代从输入张量src1中取8个数，填充到结果张量sharedTmpBuffer的8个DataBlock中（每个DataBlock的大小为32B）。</p><p>该步骤处理过程如下：</p><ul><li><p>步骤1收集的src0张量占用的空间大小 = 总迭代次数 * 每次迭代处理的元素个数 = 4 * 128 = 512。所以广播src1的元素从sharedTmpBuffer[512]开始存放；</p></li><li><p>Brcb指令迭代次数repeatTime = src1的数据长度 / 8 = 32 / 8 = 4次（Brcb指令每次迭代取8个数）；</p></li><li><p>将输入src1张量中的8个数据，填充到sharedTmpBuffer[512]位置起的8个DataBlock中去。输入是half数据类型，故每个元素复制32 / sizeof(half) = 16次。</p><p>结果：sharedTmpBuffer[512:1024] = [2, 2, 2, 2, 2, 2, 2, 2, 2, 2, 2, 2, 2, 2, 2, 2, 3, 3, ..., 33, 33]。</p></li></ul></li><li><p>步骤3. 收集的src0张量与广播后的src1张量，调用<a href="Mul.html">Mul</a>执行逐元素乘法，结果覆盖sharedTmpBuffer。</p><p>迭代计算次数：hRepeat * vRepeat = 2 * 2 = 4。</p><p>支持两种计算方式，由接口输入参数repeatMode控制（配置true或false）。</p><ul><li><p>repeatMode=false 每次迭代，src0（数据存放位置为sharedTmpBuffer[0:511]）读取8个DataBlock，每个DataBlock的每个值均与src1（数据存放位置为sharedTmpBuffer[512:1024]）的单个数值相乘。</p><ul><li>整个处理过程如下： <ul><li><p>迭代0计算过程：第1个DataBlock（sharedTmpBuffer[0:15]）到第8个DataBlock（sharedTmpBuffer[112:127]），均与src1的2相乘。</p><p>即sharedTmpBuffer[0:127] = [1 * 2, ..., 128 * 2]；</p></li><li><p>迭代1计算过程：第1个DataBlock（sharedTmpBuffer[128:143]）到第8个DataBlock（sharedTmpBuffer[240:255]），均与src1的3相乘。</p><p>即sharedTmpBuffer[128:255] = [129 * 3, ..., 256 * 3]；</p></li><li><p>迭代2计算过程：第1个DataBlock（sharedTmpBuffer[256:271]）到第8个DataBlock（sharedTmpBuffer[368:383]），均与src1的4相乘。</p><p>即sharedTmpBuffer[256:383] = [257 * 4, ..., 384 * 4]；</p></li><li><p>迭代3计算过程：第1个DataBlock（sharedTmpBuffer[384:399]）到第8个DataBlock（sharedTmpBuffer[496:511]），均与src1的5相乘。</p><p>即sharedTmpBuffer[384:511] = [385 * 5, ..., 512 * 5]。</p></li></ul></li></ul></li><li><p>repeatMode=true 每次迭代，src0（数据存放位置为sharedTmpBuffer[0:511]）读取8个DataBlock，每个DataBlock分别与src1（存放位置为sharedTmpBuffer[512:1024]）的1个数值相乘，即src0的8个DataBlock分别对应src1的8个数值。</p><ul><li>整个处理过程如下： <ul><li><p>迭代0计算过程：第1个DataBlock（sharedTmpBuffer[0:15]）与src1的2相乘，第2个DataBlock（sharedTmpBuffer[16:31]）与src1的3相乘；...依次类推，第8个DataBlock（sharedTmpBuffer[112:127]）与src1的9相乘。</p><p>即sharedTmpBuffer[0:127] = [1 * 2, ..., 16 * 2, 17 * 3, ..., 128 * 9]；</p></li><li><p>迭代1计算过程：第1个DataBlock（sharedTmpBuffer[128:143]）与src1的10相乘，第2个DataBlock（sharedTmpBuffer[144:159]）与src1的11相乘；...依次类推，第8个DataBlock（sharedTmpBuffer[240:255]）与src1的17相乘。</p><p>即sharedTmpBuffer[128:255] = [129 * 10, ..., 144 * 10, 145 * 11, ..., 256 * 17]；</p></li><li><p>迭代2计算过程：第1个DataBlock（sharedTmpBuffer[256:271]）与src1的18相乘，第2个DataBlock（sharedTmpBuffer[272:287]）与src1的19相乘；...依次类推，第8个DataBlock（sharedTmpBuffer[368:383]）与src1的25相乘。</p><p>即sharedTmpBuffer[256:383] = [257 * 18, ..., 272 * 18, 273 * 19, ..., 384 * 25]；</p></li><li><p>迭代3计算过程：第1个DataBlock（sharedTmpBuffer[384:399]）与src1的26相乘，第2个DataBlock（sharedTmpBuffer[400:415]）与src1的27相乘；...依次类推，第8个DataBlock（sharedTmpBuffer[496:511]）与src1的33相乘。</p><p>即sharedTmpBuffer[384:511] = [385 * 26, ..., 400 * 26, 401 * 27, ..., 512 * 33]。</p></li></ul></li></ul></li></ul></li><li><p>步骤4. 水平迭代累加，输出到dst。</p><p>调用<a href="Add.html">Add</a>接口完成以下处理：</p><ul><li>dst[0:127] = sharedTmpBuffer[0:127] + sharedTmpBuffer[128:255]；</li><li>dst[128:255] = sharedTmpBuffer[256:383] + sharedTmpBuffer[384:511]。</li></ul></li></ul><h2 id="函数原型">函数原型<span id="zh-cn_topic_0000002560891889_section82039854412"></span><a class="header-anchor" href="#函数原型">​</a></h2><ul><li><p>mask逐bit模式：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">template</span><span class="w"> </span><span class="o">&lt;</span><span class="k">typename</span><span class="w"> </span><span class="nc">T</span><span class="o">&gt;</span>
<span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">BilinearInterpolation</span><span class="p">(</span><span class="k">const</span><span class="w"> </span><span class="n">LocalTensor</span><span class="o">&lt;</span><span class="n">T</span><span class="o">&gt;</span><span class="w"> </span><span class="o">&amp;</span><span class="n">dst</span><span class="p">,</span><span class="w"> </span><span class="k">const</span><span class="w"> </span><span class="n">LocalTensor</span><span class="o">&lt;</span><span class="n">T</span><span class="o">&gt;</span><span class="w"> </span><span class="o">&amp;</span><span class="n">src0</span><span class="p">,</span>
<span class="w">    </span><span class="k">const</span><span class="w"> </span><span class="n">LocalTensor</span><span class="o">&lt;</span><span class="kt">uint32_t</span><span class="o">&gt;</span><span class="w"> </span><span class="o">&amp;</span><span class="n">src0Offset</span><span class="p">,</span><span class="w"> </span><span class="k">const</span><span class="w"> </span><span class="n">LocalTensor</span><span class="o">&lt;</span><span class="n">T</span><span class="o">&gt;</span><span class="w"> </span><span class="o">&amp;</span><span class="n">src1</span><span class="p">,</span><span class="w"> </span><span class="kt">uint64_t</span><span class="w"> </span><span class="n">mask</span><span class="p">[],</span><span class="w"> </span><span class="kt">uint8_t</span><span class="w"> </span><span class="n">hRepeat</span><span class="p">,</span>
<span class="w">    </span><span class="kt">bool</span><span class="w"> </span><span class="n">repeatMode</span><span class="p">,</span><span class="w"> </span><span class="kt">uint16_t</span><span class="w"> </span><span class="n">dstBlkStride</span><span class="p">,</span><span class="w"> </span><span class="kt">uint16_t</span><span class="w"> </span><span class="n">vROffset</span><span class="p">,</span><span class="w"> </span><span class="kt">uint8_t</span><span class="w"> </span><span class="n">vRepeat</span><span class="p">,</span>
<span class="w">    </span><span class="k">const</span><span class="w"> </span><span class="n">LocalTensor</span><span class="o">&lt;</span><span class="kt">uint8_t</span><span class="o">&gt;</span><span class="w"> </span><span class="o">&amp;</span><span class="n">sharedTmpBuffer</span><span class="p">);</span>
</code></pre></div></li><li><p>mask连续模式：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">template</span><span class="w"> </span><span class="o">&lt;</span><span class="k">typename</span><span class="w"> </span><span class="nc">T</span><span class="o">&gt;</span>
<span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">BilinearInterpolation</span><span class="p">(</span><span class="k">const</span><span class="w"> </span><span class="n">LocalTensor</span><span class="o">&lt;</span><span class="n">T</span><span class="o">&gt;</span><span class="w"> </span><span class="o">&amp;</span><span class="n">dst</span><span class="p">,</span><span class="w"> </span><span class="k">const</span><span class="w"> </span><span class="n">LocalTensor</span><span class="o">&lt;</span><span class="n">T</span><span class="o">&gt;</span><span class="w"> </span><span class="o">&amp;</span><span class="n">src0</span><span class="p">,</span>
<span class="w">    </span><span class="k">const</span><span class="w"> </span><span class="n">LocalTensor</span><span class="o">&lt;</span><span class="kt">uint32_t</span><span class="o">&gt;</span><span class="w"> </span><span class="o">&amp;</span><span class="n">src0Offset</span><span class="p">,</span><span class="w"> </span><span class="k">const</span><span class="w"> </span><span class="n">LocalTensor</span><span class="o">&lt;</span><span class="n">T</span><span class="o">&gt;</span><span class="w"> </span><span class="o">&amp;</span><span class="n">src1</span><span class="p">,</span><span class="w"> </span><span class="kt">uint64_t</span><span class="w"> </span><span class="n">mask</span><span class="p">,</span><span class="w"> </span><span class="kt">uint8_t</span><span class="w"> </span><span class="n">hRepeat</span><span class="p">,</span>
<span class="w">    </span><span class="kt">bool</span><span class="w"> </span><span class="n">repeatMode</span><span class="p">,</span><span class="w"> </span><span class="kt">uint16_t</span><span class="w"> </span><span class="n">dstBlkStride</span><span class="p">,</span><span class="w"> </span><span class="kt">uint16_t</span><span class="w"> </span><span class="n">vROffset</span><span class="p">,</span><span class="w"> </span><span class="kt">uint8_t</span><span class="w"> </span><span class="n">vRepeat</span><span class="p">,</span>
<span class="w">    </span><span class="k">const</span><span class="w"> </span><span class="n">LocalTensor</span><span class="o">&lt;</span><span class="kt">uint8_t</span><span class="o">&gt;</span><span class="w"> </span><span class="o">&amp;</span><span class="n">sharedTmpBuffer</span><span class="p">);</span>
</code></pre></div></li></ul><h2 id="参数说明">参数说明<span id="section622mcpsimp"></span><a class="header-anchor" href="#参数说明">​</a></h2><h3 id="模板参数及接口参数说明">模板参数及接口参数说明<a class="header-anchor" href="#模板参数及接口参数说明">​</a></h3><p><strong>表1</strong> 模板参数说明</p><table><thead><tr><th>参数名</th><th>描述</th></tr></thead><tbody><tr><td>T</td><td>操作数数据类型。</td></tr></tbody></table><p><strong>表2</strong> 参数说明</p><table><thead><tr><th>参数名</th><th>输入/输出</th><th>描述</th></tr></thead><tbody><tr><td>dst</td><td>输出</td><td>目的操作数。<br>类型为<a href="../../data_structures/LocalTensor/LocalTensor.html">LocalTensor</a>，支持的TPosition为VECIN/VECCALC/VECOUT。<br>LocalTensor的起始地址需要32字节对齐。</td></tr><tr><td>src0、src1</td><td>输入</td><td>源操作数。<br>类型为<a href="../../data_structures/LocalTensor/LocalTensor.html">LocalTensor</a>，支持的TPosition为VECIN/VECCALC/VECOUT。<br>LocalTensor的起始地址需要32字节对齐。<br>两个源操作数的数据类型需要与目的操作数保持一致。</td></tr><tr><td>src0Offset</td><td>输入</td><td>源操作数。<br>类型为<a href="../../data_structures/LocalTensor/LocalTensor.html">LocalTensor</a>，支持的TPosition为VECIN/VECCALC/VECOUT。<br>LocalTensor的起始地址需要32字节对齐。</td></tr><tr><td>mask[]/mask</td><td>输入</td><td>mask用于控制每次迭代内参与计算的元素。详细设置参考<a href="../SIMD_compute/mask.html">掩码</a>。</td></tr><tr><td>hRepeat</td><td>输入</td><td>水平方向迭代次数，取值范围为[1, 255]。</td></tr><tr><td>repeatMode</td><td>输入</td><td>迭代模式：<br>• false：每次迭代src0读取的8个DataBlock中每个值均与src1的单个数值相乘。<br>• true：每次迭代src0的每个DataBlock分别与src1的1个数值相乘，即1次迭代共消耗src0的8个DataBlock和src1的8个element。</td></tr><tr><td>dstBlkStride</td><td>输入</td><td>单次迭代内，目的操作数不同DataBlock间地址步长，以32B为单位。</td></tr><tr><td>vROffset</td><td>输入</td><td>垂直迭代间，目的操作数地址偏移量，以元素为单位，取值范围为[128, 65535)，vROffset * sizeof(T)需要保证32字节对齐。</td></tr><tr><td>vRepeat</td><td>输入</td><td>垂直方向迭代次数，取值范围为[1, 255]。</td></tr><tr><td>sharedTmpBuffer</td><td>输入</td><td>临时空间。具体空间说明请参考下面的<a href="#sharedtmpbuffer%E7%A9%BA%E9%97%B4%E8%AF%B4%E6%98%8E">sharedTmpBuffer空间说明</a>。</td></tr></tbody></table><h3 id="sharedTmpBuffer空间说明">sharedTmpBuffer空间说明<a class="header-anchor" href="#sharedTmpBuffer空间说明">​</a></h3><div data-filter="950"><ul><li>针对Ascend 950PR/Ascend 950DT，不需要分配临时空间。</li></ul></div><div data-filter="A3"><ul><li>针对Atlas A3 训练系列产品/Atlas A3 推理系列产品，需要保证至少分配了src0.GetSize() * 32 + src1.GetSize() * 32字节的空间。</li></ul></div><div data-filter="910b"><ul><li>针对Atlas A2 训练系列产品/Atlas A2 推理系列产品，需要保证至少分配了src0.GetSize() * 32 + src1.GetSize() * 32字节的空间。</li></ul></div><div data-filter="310p"><ul><li>针对Atlas 推理系列产品AI Core，需要保证至少分配了src0OffsetLocal.GetSize() * sizeof(uint32_t)字节的空间。</li></ul></div><h2 id="数据类型">数据类型<a class="header-anchor" href="#数据类型">​</a></h2><p>支持的数据类型为：half。</p><h2 id="返回值说明">返回值说明<span id="section640mcpsimp"></span><a class="header-anchor" href="#返回值说明">​</a></h2><p>无</p><h2 id="约束说明">约束说明<span id="section633mcpsimp"></span><a class="header-anchor" href="#约束说明">​</a></h2><ul><li>操作数地址对齐要求请参见<a href="../../../general_description_and_constraints.html">通用地址对齐约束</a>。</li><li>src0、src1、src0Offset之间不允许地址重叠，且两个垂直repeat的目的地址之间不允许地址重叠。</li><li>参数vROffset的取值范围为[128, 65535)。</li><li>水平方向迭代次数，取值范围为[1, 255]。</li><li>垂直方向迭代次数，取值范围为[1, 255]。</li><li>输入的临时空间sharedTmpBuffer，空间大小要求请参考<a href="#sharedtmpbuffer%E7%A9%BA%E9%97%B4%E8%AF%B4%E6%98%8E">sharedTmpBuffer空间说明</a>。</li><li>参数src0Offset的取值要求如下： <ul><li>取值应保证src0元素类型位宽对齐。</li><li>偏移地址后需要32字节对齐。</li><li>偏移地址后不能超出Unified Buffer（UB）大小数据的范围。</li><li>地址偏移的取值范围：不能超出uint32_t的范围。</li></ul></li><li>当参数repeatMode配置为true时，需确保src1的有效数据长度*16 ≥ src0的数据长度。</li></ul><h2 id="调用示例">调用示例<span id="section642mcpsimp"></span><a class="header-anchor" href="#调用示例">​</a></h2><ul><li><p>接口样例-mask连续模式</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">AscendC</span><span class="o">::</span><span class="n">LocalTensor</span><span class="o">&lt;</span><span class="n">half</span><span class="o">&gt;</span><span class="w"> </span><span class="n">dstLocal</span><span class="p">,</span><span class="w"> </span><span class="n">src0Local</span><span class="p">,</span><span class="w"> </span><span class="n">src1Local</span><span class="p">;</span><span class="w"> </span><span class="c1">// repeatMode = false，src1Local的数据长度为16即可</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">LocalTensor</span><span class="o">&lt;</span><span class="kt">uint32_t</span><span class="o">&gt;</span><span class="w"> </span><span class="n">src0OffsetLocal</span><span class="p">;</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">LocalTensor</span><span class="o">&lt;</span><span class="kt">uint8_t</span><span class="o">&gt;</span><span class="w"> </span><span class="n">tmpLocal</span><span class="p">;</span>
<span class="kt">uint64_t</span><span class="w"> </span><span class="n">mask</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">128</span><span class="p">;</span><span class="w">        </span><span class="c1">// mask连续模式</span>
<span class="kt">uint8_t</span><span class="w"> </span><span class="n">hRepeat</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">2</span><span class="p">;</span><span class="w">        </span><span class="c1">// 水平迭代2次</span>
<span class="kt">bool</span><span class="w"> </span><span class="n">repeatMode</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="nb">false</span><span class="p">;</span><span class="w">    </span><span class="c1">// 迭代模式</span>
<span class="kt">uint16_t</span><span class="w"> </span><span class="n">dstBlkStride</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">1</span><span class="p">;</span><span class="w">  </span><span class="c1">// 单次迭代内数据连续写入</span>
<span class="kt">uint16_t</span><span class="w"> </span><span class="n">vROffset</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">128</span><span class="p">;</span><span class="w">    </span><span class="c1">// 相邻迭代间数据连续写入</span>
<span class="kt">uint8_t</span><span class="w"> </span><span class="n">vRepeat</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">2</span><span class="p">;</span><span class="w">        </span><span class="c1">// 垂直迭代2次</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">BilinearInterpolation</span><span class="p">(</span><span class="n">dstLocal</span><span class="p">,</span><span class="w"> </span><span class="n">src0Local</span><span class="p">,</span><span class="w"> </span><span class="n">src0OffsetLocal</span><span class="p">,</span><span class="w"> </span><span class="n">src1Local</span><span class="p">,</span><span class="w"> </span><span class="n">mask</span><span class="p">,</span><span class="w"> </span><span class="n">hRepeat</span><span class="p">,</span><span class="w"> </span><span class="n">repeatMode</span><span class="p">,</span>
<span class="w">            </span><span class="n">dstBlkStride</span><span class="p">,</span><span class="w"> </span><span class="n">vROffset</span><span class="p">,</span><span class="w"> </span><span class="n">vRepeat</span><span class="p">,</span><span class="w"> </span><span class="n">tmpLocal</span><span class="p">);</span>
</code></pre></div></li><li><p>接口样例-mask逐bit模式</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">AscendC</span><span class="o">::</span><span class="n">LocalTensor</span><span class="o">&lt;</span><span class="n">half</span><span class="o">&gt;</span><span class="w"> </span><span class="n">dstLocal</span><span class="p">,</span><span class="w"> </span><span class="n">src0Local</span><span class="p">,</span><span class="w"> </span><span class="n">src1Local</span><span class="p">;</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">LocalTensor</span><span class="o">&lt;</span><span class="kt">uint32_t</span><span class="o">&gt;</span><span class="w"> </span><span class="n">src0OffsetLocal</span><span class="p">;</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">LocalTensor</span><span class="o">&lt;</span><span class="kt">uint8_t</span><span class="o">&gt;</span><span class="w"> </span><span class="n">tmpLocal</span><span class="p">;</span>
<span class="kt">uint64_t</span><span class="w"> </span><span class="n">mask</span><span class="p">[</span><span class="mi">2</span><span class="p">]</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="p">{</span><span class="w"> </span><span class="n">UINT64_MAX</span><span class="p">,</span><span class="w"> </span><span class="n">UINT64_MAX</span><span class="w"> </span><span class="p">};</span><span class="w"> </span><span class="c1">// mask逐bit模式</span>
<span class="kt">uint8_t</span><span class="w"> </span><span class="n">hRepeat</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">2</span><span class="p">;</span><span class="w">        </span><span class="c1">// 水平迭代2次</span>
<span class="kt">bool</span><span class="w"> </span><span class="n">repeatMode</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="nb">false</span><span class="p">;</span><span class="w">    </span><span class="c1">// 迭代模式</span>
<span class="kt">uint16_t</span><span class="w"> </span><span class="n">dstBlkStride</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">1</span><span class="p">;</span><span class="w">  </span><span class="c1">// 单次迭代内数据连续写入</span>
<span class="kt">uint16_t</span><span class="w"> </span><span class="n">vROffset</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">128</span><span class="p">;</span><span class="w">    </span><span class="c1">// 相邻迭代间数据连续写入</span>
<span class="kt">uint8_t</span><span class="w"> </span><span class="n">vRepeat</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">2</span><span class="p">;</span><span class="w">        </span><span class="c1">// 垂直迭代2次</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">BilinearInterpolation</span><span class="p">(</span><span class="n">dstLocal</span><span class="p">,</span><span class="w"> </span><span class="n">src0Local</span><span class="p">,</span><span class="w"> </span><span class="n">src0OffsetLocal</span><span class="p">,</span><span class="w"> </span><span class="n">src1Local</span><span class="p">,</span><span class="w"> </span><span class="n">mask</span><span class="p">,</span><span class="w"> </span><span class="n">hRepeat</span><span class="p">,</span><span class="w"> </span><span class="n">repeatMode</span><span class="p">,</span>
<span class="w">            </span><span class="n">dstBlkStride</span><span class="p">,</span><span class="w"> </span><span class="n">vROffset</span><span class="p">,</span><span class="w"> </span><span class="n">vRepeat</span><span class="p">,</span><span class="w"> </span><span class="n">tmpLocal</span><span class="p">);</span>
</code></pre></div></li></ul><p>结果示例如下：</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>输入数据(src0Local,half): [1,2,3,...,512]
输入数据(src1Local,half): [2,3,4,...,17]
输入数据(src0OffsetLocal,uint32_t): [0,32,64,...,992]
输出数据(dstLocal,half): [389, 394, 399, 404, ...,4096]
</code></pre></div></article></div>`,1)])])}const w=a(e,[["render",r]]);export{m as __pageData,w as default};
